def f1():
    ops=[['A1','A2','A3','A4'],['A5','A6','NOP','NOP'],['A7','NOP','NOP','NOP'],['A8','NOP','NOP','NOP']]
    o=''
    for c in range(4):o+=T(83+c*70,14,f'слот {c+1}','t-s mu')
    for r,row in enumerate(ops):
        y=22+r*34;o+=TL(4,y+19,f'сөз {r+1}','t-s mu')
        for c,v in enumerate(row):
            if v=='NOP':o+=B(50+c*70,y,66,30,'NOP','soft','t-s mu')
            else:o+=B(50+c*70,y,66,30,v,'bxa' if r==0 else 'bx','t-s t-b' if r==0 else 't-s')
    return o
