for i,p in enumerate(L):
    assert p.count('class="check"')==1,i
    assert p.startswith('<h2>'),i
    txt=re.sub(r'<svg.*?</svg>|<figure>.*?</figure>|<pre>.*?</pre>|<aside class="check">.*?</aside>|<table>.*?</table>','',p,flags=re.S)
    for s in re.split(r'(?<=[.!?])\s+',re.sub(r'<[^>]+>',' ',txt)):
        if len(s.split())>25:print('LONG',i,len(s.split()),s[:90])
    for q in re.findall(r'<p>(.*?)</p>',txt,flags=re.S):
        if len(re.split(r'(?<=[.!?])\s+',re.sub(r'<[^>]+>','',q)))>5:print('PARA>4',i,q[:60])

new_gloss=[
("Принстон архитектурасы","принстонская архитектура (= фон Неймана)","Princeton architecture",""),
("екілік үйлесімсіздік","двоичная несовместимость","binary incompatibility",""),
("детерминделген орындау","детерминированное выполнение","deterministic execution",""),
("нақты уақыт жүйесі","система реального времени","real-time system",""),
("EPIC","EPIC (явный параллелизм команд)","explicitly parallel instruction computing","EPIC"),
("командалар жады","память команд","program memory",""),
("деректер жады","память данных","data memory",""),
("командалар шинасы","шина команд","instruction bus",""),
("жадпен интерфейс блогы","блок интерфейса памяти","memory interface unit",""),
("модификацияланған Гарвард архитектурасы","модифицированная гарвардская архитектура","modified Harvard architecture",""),
]
def pack(lid,order,title,parts,fn):
    d={"format":"besminut-pack","version":1,"course":course,"lectures":[{"id":lid,"order":order,"title":title,"source":"material","parts":parts,"cards":[]}]}
    json.dump(d,open(f'{OUT}/{fn}','w',encoding='utf-8'),ensure_ascii=False)
    print(fn,len(parts),'parts',os.path.getsize(f'{OUT}/{fn}')//1024,'KB')
if __name__=='__main__':
    pack('microprocessors-06-vliw-princeton-harvard',6,'6-сабақ. VLIW, Принстондық және Гарвардтық архитектуралар',L,'06-vliw-princeton-harvard.json')
    g=json.load(open(f'{OUT}/glossary.json',encoding='utf-8'));have={x['kk'] for x in g}
    abbrs={x['abbr'] for x in g if x['abbr']}
    for a,b,c,d in new_gloss:
        if a not in have:
            assert not d or d not in abbrs,d
            g.append({"kk":a,"ru":b,"en":c,"abbr":d})
    json.dump(g,open(f'{OUT}/glossary.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
    print('glossary',len(g))
    packs=[]
    for f in sorted(glob.glob(f'{ROOT}/courses/*/*.json')):
        n=os.path.basename(f)
        if n=='glossary.json':continue
        try:
            d=json.load(open(f,encoding='utf-8'))
            if d.get('format')!='besminut-pack':continue
        except Exception:continue
        packs.append({"path":os.path.relpath(f,ROOT).replace(os.sep,'/'),"v":hashlib.sha1(open(f,'rb').read()).hexdigest()[:12]})
    json.dump({"packs":packs},open(f'{ROOT}/courses/index.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
    print('index',len(packs))
